def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [x for row in grid for x in row]
    bg = max(set(vals), key=vals.count)
    out = [row[:] for row in grid]

    # Locate the full-length divider.
    vertical = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if vertical is not None:
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and grid[r][c] != 2]
        if not cells:
            return out
        left = min(c for r, c in cells)
        right = max(c for r, c in cells)
        if right < vertical:
            shift = vertical - 1 - right
            stripe = left + shift - 1
        else:
            shift = vertical + 1 - left
            stripe = right + shift + 1

        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r][c + shift] = grid[r][c]
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
        return out

    horizontal = next((r for r in range(h) if all(x == 2 for x in grid[r])), None)
    if horizontal is None:
        return out
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    if not cells:
        return out
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    if bottom < horizontal:
        shift = horizontal - 1 - bottom
        stripe = top + shift - 1
    else:
        shift = horizontal + 1 - top
        stripe = bottom + shift + 1

    for r, c in cells:
        out[r][c] = bg
    for r, c in cells:
        out[r + shift][c] = grid[r][c]
    if 0 <= stripe < h:
        out[stripe] = [8] * w
    return out
